mapper.select:
select distinct t.id, t.create_user_id as createUserId, t.create_user_name as createUserName, t.create_time as createTime, t.update_user_id as updateUserId, t.update_user_name as updateUserName, t.update_time as updateTime, t.version, t.is_deleted as isDeleted, t.code, t.source_id as sourceId, t.source_code as sourceCode, t.source_type as sourceType, t.type, t.is_use as isUse, t.pack_status as packStatus, t.is_difference as isDifference, t.is_move_warehouse as isMoveWarehouse, t.sku_species_qty as skuSpeciesQty, t.total_qty as totalQty, t.remark, t.reject_description as rejectDescription, t.invalid_status as invalidStatus, t.invalid_remark as invalidRemark, t.invalid_time as invalidTime, t.operate_user_id as operateUserId, t.operate_user_name as operateUserName, t.check_user_id as checkUserId, t.check_user_name as checkUserName, pt.supplier_id as supplierId, pt.supplier_name as supplierName from after_sale_pack t left join po_return pt on t.source_id = pt.id and pt.is_deleted = false left join after_sale_pack_detail dt on t.id = dt.main_id and dt.is_deleted = false WHERE 1 = 1 and t.is_deleted = false
AND ${params.sqlMap.default}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.update_time DESC

SELECT t.code, t.type AS type, t.pack_status AS packStatus, t.is_use AS isUse, t.invalid_status AS invalidStatus, t.invalid_remark AS invalidRemark, t.invalid_time AS invalidTime, t.total_qty AS totalQty, t.sku_species_qty AS skuSpeciesQty, t.create_user_name AS createUserName, t.create_time AS createTime, t.operate_user_name AS operateUserName, t.check_user_name AS checkUserName, t.remark, pt.supplier_name AS supplierName, dt.sku_no AS skuNo, dt.pack_qty AS packQty, wl.code AS outWarehouseLocationCode FROM after_sale_pack t LEFT JOIN po_return pt ON t.source_id = pt.id AND pt.is_deleted = FALSE LEFT JOIN after_sale_pack_detail dt ON t.id = dt.main_id AND dt.is_deleted = FALSE LEFT JOIN warehouse_location wl ON dt.out_warehouse_location_id = wl.id AND wl.is_deleted = FALSE WHERE t.is_deleted = FALSE
AND ${params.sqlMap.default}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.update_time DESC, dt.id ASC
